create table SCHEMA_SOURCE
(
    id          varchar(355)     not null
        primary key,
    table_name  varchar(155)     not null,
    column_name varchar(155)     not null,
    datatype    varchar(100)     not null,
    _enabled    bit    default 0 not null,
    indexed     bit    default 0 not null,
    ssTag       varchar(10)      not null,
    single_mult char             not null,
    local_ref   bit              not null,
    insert_date bigint default replace(replace(replace(CONVERT([varchar](19), sysdatetime(), 20), '-', ''), ':', ''),
                                       ' ', '')
)
go

create index tab_enable_idx
    on SCHEMA_SOURCE (table_name, _enabled)
go

create index tab_col_idx
    on SCHEMA_SOURCE (table_name, column_name)
go

